<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import Icon from '../components/Icon.vue'
import { useAuthStore } from '../stores/auth'
import { useIaStore, type AgentMode, type IaConnector, type IaPolicy } from '../stores/ia'

const ia = useIaStore(); const auth = useAuthStore()
const text = ref(''); const showNew = ref(false); const mode = ref<AgentMode>('ask'); const title = ref('')
const showAdmin = ref(false); const configKey = ref(''); const status = ref(''); const shellConfirmation = ref('')
const configDraft = ref({ proveedor: 'deepseek', baseUrl: 'https://api.deepseek.com', modelo: 'deepseek-chat', habilitado: false, maxIteraciones: 8, temperatura: 0.2 })
const policyDraft = ref<IaPolicy | null>(null); const connectorKeys = ref<Record<string, string>>({})
const can = (permission: string) => auth.can(permission)
const canAdmin = computed(() => auth.user?.isSuperadmin && can('ia.config.view'))
const canAgentMode = computed(() => can('ia.agent.act'))
const canSuperMode = computed(() => !!auth.user?.isSuperadmin && can('ia.shell.execute'))
const messages = computed(() => ia.selected?.mensajes ?? [])
const modeLabel = (value: AgentMode) => ({ ask: 'Preguntar', agente: 'Agente', super: 'Super' }[value])
const time = (value?: string) => value ? new Date(value).toLocaleString('es-MX', { dateStyle: 'medium', timeStyle: 'short' }) : ''
const currency = (value?: number) => new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'USD', maximumFractionDigits: 4 }).format(value || 0)
const pretty = (value: unknown) => JSON.stringify(value, null, 2)

watch(() => ia.config, (config) => {
  if (!config) return
  configDraft.value = { proveedor: config.proveedor, baseUrl: config.baseUrl, modelo: config.modelo, habilitado: config.habilitado, maxIteraciones: config.maxIteraciones, temperatura: config.temperatura }
}, { deep: true })

async function openConversation(item: any) { await ia.select(item); await nextTick(() => document.querySelector('.message-list')?.scrollTo(0, 1e9)) }
async function create() { await ia.create(mode.value, title.value); showNew.value = false; title.value = ''; text.value = '' }
async function submit() { if (!text.value.trim()) return; const value = text.value; text.value = ''; await ia.send(value) }
async function openAdmin() { showAdmin.value = true; status.value = ''; await ia.loadAdmin(); policyDraft.value = ia.policies[0] ? JSON.parse(JSON.stringify(ia.policies[0])) as IaPolicy : null }
async function saveConfig() { status.value = ''; await ia.saveConfig({ ...configDraft.value, ...(configKey.value ? { apiKey: configKey.value } : {}) }); configKey.value = ''; status.value = 'Configuración guardada. La llave no vuelve a mostrarse.' }
async function testConfig() { status.value = ''; try { const result = await ia.testConfig(); status.value = result.detalle; await ia.loadAdmin() } catch (error) { status.value = error instanceof Error ? error.message : 'No se pudo probar la conexión.' } }
async function savePolicy() { if (!policyDraft.value) return; await ia.savePolicy(policyDraft.value); status.value = 'Playbook guardado.' }
async function saveConnector(connector: IaConnector) { const apiKey = connectorKeys.value[connector.id]; await ia.saveConnector({ ...connector, ...(apiKey ? { apiKey } : {}) }); connectorKeys.value[connector.id] = ''; status.value = `Conector ${connector.nombre} guardado.` }
async function toggleShell() { if (!ia.selected) return; if (ia.selected.shellHabilitado) { await ia.setShell(false); return }; await ia.setShell(true, shellConfirmation.value); shellConfirmation.value = '' }
onMounted(() => void ia.load())
</script>

<template>
  <main class="assistant-page">
    <header class="hero">
      <div><span class="eyebrow">Asistente del laboratorio</span><h1>FagoLab IA</h1><p>Consulta datos, protocolo y bitácora; las acciones siempre requieren confirmación.</p></div>
      <div class="hero-actions"><button v-if="canAdmin" class="btn" @click="openAdmin"><Icon name="shield" :size="16" /> Configuración</button><button class="btn btn-primary" @click="showNew=true"><Icon name="plus" :size="16" /> Nueva conversación</button></div>
    </header>
    <p v-if="ia.error" class="alert">{{ ia.error }}</p>
    <section class="workspace card">
      <aside class="conversations"><header><b>Conversaciones</b><small>{{ ia.conversations.length }}</small></header><button v-for="item in ia.conversations" :key="item.id" class="conversation" :class="{ active: ia.selected?.id === item.id }" @click="openConversation(item)"><span :class="item.modo"><Icon :name="item.modo === 'ask' ? 'brain' : 'sparkles'" :size="15" /></span><div><b>{{ item.titulo || 'Nueva conversación' }}</b><small>{{ item.ultimoMensaje || modeLabel(item.modo) }}</small></div><em>{{ modeLabel(item.modo) }}</em></button><p v-if="!ia.loading && !ia.conversations.length" class="empty">Aún no hay conversaciones.</p></aside>
      <section v-if="ia.selected" class="thread">
        <header class="thread-head"><div><span class="mode-pill" :class="ia.selected.modo">{{ modeLabel(ia.selected.modo) }}</span><h2>{{ ia.selected.titulo || 'Nueva conversación' }}</h2><p v-if="ia.selected.modo === 'super'" class="danger">Modo Super: revisa cada comando antes de aprobarlo.</p></div><button v-if="ia.selected.modo === 'super' && canSuperMode" class="tiny" :class="{ dangerButton: ia.selected.shellHabilitado }" @click="toggleShell">{{ ia.selected.shellHabilitado ? 'Deshabilitar shell' : 'Habilitar shell' }}</button></header>
        <div v-if="ia.selected.modo === 'super' && !ia.selected.shellHabilitado && canSuperMode" class="shell-optin"><b>Shell desactivado.</b><span>Escribe <code>HABILITAR SHELL</code> para permitir comandos locales solo en esta conversación.</span><input v-model="shellConfirmation" placeholder="HABILITAR SHELL" /></div>
        <div class="message-list"><article v-for="message in messages" :key="message.id" :class="['message', message.rol]"><b>{{ message.rol === 'user' ? 'Tú' : message.rol === 'assistant' ? 'FagoLab IA' : message.rol }}</b><p>{{ message.contenido }}</p><details v-if="message.toolCalls?.length"><summary>Herramientas solicitadas</summary><pre>{{ pretty(message.toolCalls) }}</pre></details><time>{{ time(message.createdAt) }}</time></article><article v-if="ia.isRunning && !messages.length" class="message assistant"><b>FagoLab IA</b><p>Preparando respuesta…</p></article></div>
        <aside v-if="ia.reasoning" class="reasoning"><b>Razonamiento del agente</b><p>{{ ia.reasoning }}</p></aside>
        <section v-if="ia.proposals.length" class="proposals"><h3>Acciones por confirmar</h3><article v-for="proposal in ia.proposals" :key="proposal.id"><div><b>{{ proposal.nombre }}</b><span :class="proposal.riesgo">{{ proposal.riesgo || 'revisar' }}</span><p>{{ proposal.descripcion }}</p><pre>{{ pretty(proposal.argumentos) }}</pre></div><footer v-if="proposal.estado === 'propuesta'"><button class="btn" @click="ia.resolveProposal(proposal, false)">Rechazar</button><button v-if="canAgentMode" class="btn btn-primary" @click="ia.resolveProposal(proposal, true)">Aprobar</button></footer><small v-else>Estado: {{ proposal.estado }}</small></article></section>
        <form class="composer" @submit.prevent="submit"><textarea v-model="text" :disabled="ia.sending" placeholder="Pregunta por los datos, una tarea o un protocolo…" @keydown.enter.exact.prevent="submit"/><button v-if="ia.isRunning" type="button" class="btn" @click="ia.cancel">Cancelar</button><button class="btn btn-primary" :disabled="!text.trim() || ia.sending">Enviar</button></form>
      </section>
      <section v-else class="start"><Icon name="brain" :size="35"/><h2>Un asistente que respeta tus permisos</h2><p>Abre una conversación o crea una nueva para consultar el proyecto.</p><button class="btn btn-primary" @click="showNew=true">Comenzar</button></section>
    </section>

    <div v-if="showNew" class="modal-layer"><form class="modal card" @submit.prevent="create"><header><h2>Nueva conversación</h2><button type="button" @click="showNew=false">×</button></header><label>Título opcional<input v-model.trim="title" maxlength="120" placeholder="Ej. Revisar resultados de PCR" /></label><fieldset><legend>Modo de trabajo</legend><label><input v-model="mode" type="radio" value="ask" /> <b>Preguntar</b><small>Solo consulta datos y fuentes.</small></label><label v-if="canAgentMode"><input v-model="mode" type="radio" value="agente" /> <b>Agente</b><small>Puede proponer cambios; tú los apruebas uno por uno.</small></label><label v-if="canSuperMode"><input v-model="mode" type="radio" value="super" /> <b>Super</b><small>Incluye shell local tras activar la advertencia.</small></label></fieldset><footer><button type="button" class="btn" @click="showNew=false">Cancelar</button><button class="btn btn-primary">Crear</button></footer></form></div>

    <div v-if="showAdmin" class="modal-layer admin-layer"><section class="admin card"><header><div><span class="eyebrow">Solo superadministración</span><h2>Configuración del asistente</h2></div><button @click="showAdmin=false">×</button></header><p v-if="status" class="notice">{{ status }}</p><div class="admin-grid"><form class="setting" @submit.prevent="saveConfig"><h3>Proveedor y llave</h3><label>Proveedor<input v-model="configDraft.proveedor" required /></label><label>URL base<input v-model="configDraft.baseUrl" type="url" required /></label><label>Modelo<input v-model="configDraft.modelo" required /></label><label>Nueva llave API <small>{{ ia.config?.apiKeyPista ? `Configurada: ${ia.config.apiKeyPista}` : 'Sin llave configurada' }}</small><input v-model="configKey" type="password" autocomplete="new-password" placeholder="Solo se envía al guardar" /></label><div class="row"><label><input v-model="configDraft.habilitado" type="checkbox" /> Habilitar agente</label><label>Máx. iteraciones<input v-model.number="configDraft.maxIteraciones" type="number" min="1" max="50" /></label><label>Temperatura<input v-model.number="configDraft.temperatura" type="number" min="0" max="2" step="0.1" /></label></div><p v-if="ia.config?.verificadoAt" class="verify" :class="{ bad: ia.config?.verificadoOk === false }">{{ ia.config?.verificadoOk ? 'Verificado' : 'Error de verificación' }} · {{ ia.config?.verificadoDetalle }}</p><footer><button type="button" class="btn" @click="testConfig">Probar conexión</button><button class="btn btn-primary">Guardar</button></footer></form>
        <form v-if="policyDraft" class="setting wide" @submit.prevent="savePolicy"><h3>Playbook y política</h3><label>Nombre<input v-model="policyDraft.nombre" /></label><label>Prompt del sistema<textarea v-model="policyDraft.promptSistema" rows="8" /></label><div class="row"><label>Dominios permitidos <input :value="policyDraft.dominiosPermitidos.join(', ')" @change="policyDraft.dominiosPermitidos=($event.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)" placeholder="editorial.org, crossref.org" /></label><label>Dominios bloqueados <input :value="policyDraft.dominiosBloqueados.join(', ')" @change="policyDraft.dominiosBloqueados=($event.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)" /></label></div><footer><button class="btn btn-primary">Guardar política</button></footer></form>
        <section class="setting wide"><h3>Conectores</h3><article v-for="connector in ia.connectors" :key="connector.id" class="connector"><div><b>{{ connector.nombre }}</b><small>{{ connector.tipo }} · {{ connector.apiKeyPista || 'sin llave' }}</small></div><label>URL <input v-model="connector.baseUrl" /></label><label>Llave nueva<input v-model="connectorKeys[connector.id]" type="password" autocomplete="new-password" placeholder="No se muestra la actual" /></label><label><input v-model="connector.habilitado" type="checkbox" /> Activo</label><button class="btn" @click="saveConnector(connector)">Guardar</button></article></section>
        <section v-if="ia.usage" class="setting wide usage"><h3>Uso acumulado</h3><div><b>{{ ia.usage.conversaciones }}</b><span>conversaciones</span></div><div><b>{{ ia.usage.tokensEntrada + ia.usage.tokensSalida }}</b><span>tokens</span></div><div><b>{{ currency(ia.usage.costo) }}</b><span>costo estimado</span></div></section>
      </div></section></div>
  </main>
</template>

<style scoped>
.assistant-page{max-width:1420px;margin:auto;padding:28px}.hero,.hero-actions,.thread-head,.modal header,.modal footer,.admin>header,.setting footer,.connector,.row{display:flex;align-items:center;justify-content:space-between;gap:12px}.hero{align-items:end;margin-bottom:20px}.eyebrow{color:var(--teal-600);font-size:.68rem;font-weight:900;letter-spacing:.09em;text-transform:uppercase}.hero h1{margin:5px 0;font-size:1.8rem}.hero p{color:var(--muted);font-size:.8rem}.workspace{display:grid;grid-template-columns:300px minmax(0,1fr);min-height:650px;overflow:hidden;border:1px solid var(--line);border-radius:17px;background:#fff}.conversations{overflow:auto;border-right:1px solid var(--line)}.conversations>header{display:flex;justify-content:space-between;padding:15px;border-bottom:1px solid var(--line);font-size:.8rem}.conversations header small{color:var(--muted)}.conversation{display:flex;gap:9px;width:100%;padding:13px;border-bottom:1px solid var(--line-soft);text-align:left}.conversation:hover,.conversation.active{background:var(--teal-50)}.conversation>span{display:grid;place-items:center;width:31px;height:31px;border-radius:9px;color:#08766d;background:#e9fbf6}.conversation>span.agente{color:#805207;background:#fff5df}.conversation>span.super{color:#a42119;background:#fff0ee}.conversation div{display:grid;min-width:0;gap:2px}.conversation b,.conversation small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation b{font-size:.73rem}.conversation small{color:var(--muted);font-size:.63rem}.conversation em{align-self:center;margin-left:auto;color:var(--muted);font-size:.56rem;font-style:normal}.thread{display:flex;min-width:0;flex-direction:column}.thread-head{align-items:start;padding:17px 20px;border-bottom:1px solid var(--line)}.thread-head h2{margin-top:6px;font-size:1rem}.mode-pill{padding:3px 7px;border-radius:10px;color:#08766d;background:#e9fbf6;font-size:.62rem;font-weight:900}.mode-pill.agente{color:#805207;background:#fff5df}.mode-pill.super,.danger{color:#a42119;background:#fff0ee}.danger{margin-top:7px;padding:5px 7px;border-radius:7px;font-size:.66rem}.message-list{display:flex;flex:1;flex-direction:column;gap:10px;overflow:auto;padding:20px}.message{align-self:flex-start;max-width:min(780px,80%);padding:11px 13px;border-radius:13px 13px 13px 2px;background:var(--line-soft)}.message.user{align-self:flex-end;border-radius:13px 13px 2px;background:var(--teal-50)}.message.tool{font-family:monospace}.message b{font-size:.67rem}.message p{margin:4px 0;white-space:pre-wrap;font-size:.79rem;line-height:1.5}.message time{color:var(--muted);font-size:.58rem}.message details{margin-top:6px;font-size:.65rem}.message pre,.proposals pre{overflow:auto;margin-top:5px;padding:7px;border-radius:7px;background:#10273a;color:#d5ebf0;font-size:.62rem}.reasoning{margin:0 20px;padding:10px;border-radius:9px;color:#5b4700;background:#fff9df;font-size:.7rem}.reasoning p{margin-top:4px;white-space:pre-wrap}.proposals{margin:15px 20px;padding:13px;border:1px solid #f0d690;border-radius:12px;background:#fffdf4}.proposals h3{font-size:.8rem}.proposals article{display:flex;justify-content:space-between;gap:14px;padding:12px 0;border-top:1px solid #f0dfb2}.proposals article:first-of-type{border:0}.proposals b{font-size:.75rem}.proposals p{margin:5px 0;color:var(--muted);font-size:.67rem}.proposals span{margin-left:7px;padding:2px 5px;border-radius:7px;background:#fff0ee;color:#a42119;font-size:.58rem}.proposals footer{display:flex;align-items:center;gap:7px}.composer{display:flex;gap:10px;padding:14px;border-top:1px solid var(--line)}textarea,input{outline:0}.composer textarea{flex:1;min-height:42px;max-height:130px;padding:10px;border:1px solid var(--line);border-radius:10px;resize:vertical}.start{display:grid;place-items:center;align-content:center;gap:10px;padding:30px;color:var(--muted);text-align:center}.start h2{color:var(--ink);font-size:1rem}.alert,.notice{margin-bottom:12px;padding:10px;border-radius:9px;color:#a42119;background:#fff0ee;font-size:.75rem}.notice{color:#08766d;background:#e9fbf6}.modal-layer{position:fixed;z-index:90;inset:0;display:grid;place-items:center;padding:18px;background:#10273a77}.modal{display:grid;gap:15px;width:min(520px,100%);padding:22px}.modal header button,.admin>header>button{font-size:1.5rem;color:var(--muted)}.modal label,.modal fieldset label,.setting label{display:grid;gap:5px;font-size:.74rem;font-weight:800}.modal input,.setting input,.setting textarea{padding:9px;border:1px solid var(--line);border-radius:8px;background:#fff}.modal fieldset{display:grid;gap:10px;border:1px solid var(--line);border-radius:10px}.modal fieldset label{grid-template-columns:auto 1fr;align-items:center}.modal fieldset small{grid-column:2;color:var(--muted);font-weight:400}.admin-layer{align-items:start;overflow:auto}.admin{width:min(1080px,100%);margin:auto;padding:22px}.admin-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:15px}.setting{display:grid;gap:10px;padding:15px;border:1px solid var(--line);border-radius:12px}.setting h3{font-size:.88rem}.setting label small{color:var(--muted);font-weight:400}.setting.wide{grid-column:1/-1}.row{align-items:end;justify-content:start;flex-wrap:wrap}.row label{min-width:150px}.verify{padding:7px;border-radius:7px;color:#08766d;background:#e9fbf6;font-size:.68rem}.verify.bad{color:#a42119;background:#fff0ee}.connector{align-items:end;flex-wrap:wrap;padding:11px 0;border-top:1px solid var(--line-soft)}.connector:first-of-type{border:0}.connector>div{display:grid;gap:3px;margin-right:auto}.connector small{color:var(--muted);font-size:.63rem}.usage{display:flex;gap:30px;flex-wrap:wrap}.usage h3{width:100%}.usage div{display:grid;gap:4px}.usage b{font-size:1.15rem}.usage span{color:var(--muted);font-size:.65rem}.dangerButton{color:#a42119;border-color:#f1b4ae;background:#fff0ee}@media(max-width:780px){.assistant-page{padding:18px}.hero{align-items:start;flex-direction:column}.workspace{grid-template-columns:1fr}.conversations{max-height:220px;border-right:0;border-bottom:1px solid var(--line)}.thread{min-height:500px}.admin-grid{grid-template-columns:1fr}.proposals article{display:block}.proposals footer{margin-top:9px}.connector{align-items:stretch;display:grid;grid-template-columns:1fr}.connector>div{margin:0}.hero-actions{width:100%}}
</style>
